{
  "hallazgos": [
    {
      "clasificacion": "NO_CONFORMIDAD",
      "justificacion": "Se evidencia el incumplimiento de requisitos documentales obligatorios al verificarse la ausencia de registros de valoración de enfermería en una muestra de historias clínicas evaluadas.",
      "hallazgo_corregido": "Durante la auditoría al proceso de Hospitalización se evidenció que en 5 de 20 historias clínicas revisadas no se encontró registrada la valoración de enfermería, incumpliendo la conservación de información documentada para tener la confianza de que los procesos se realizan según lo planificado y el control de la provisión del servicio bajo condiciones controladas, establecido en la NTC-ISO 9001:2015, numerales 4.4 y 8.5.1.",
      "criterio_requisito": "NTC-ISO 9001:2015, numerales 4.4 y 8.5.1",
      "evidencia": "En 5 de 20 historias clínicas revisadas no se encontró registrada la valoración de enfermería requerida.",
      "criterios_citados": [
        {
          "criterio_id": "0e29270c-fc1f-4ce5-a61f-5f763ad5bbfb",
          "numeral": "4.4",
          "documento": "NTC-ISO 9001:2015"
        },
        {
          "criterio_id": "92b3dba7-f25f-4b16-b11c-6fb25eb7da05",
          "numeral": "8.5.1",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": {
        "descripcion": "Posibilidad de fallas en la continuidad del cuidado o decisiones clínicas inadecuadas debido a la falta de registro de la valoración de enfermería en la historia clínica, lo que podría generar eventos adversos o complicaciones en la evolución del paciente.",
        "dimension": "CALIDAD_SEGURIDAD_PACIENTE",
        "probabilidad": 3,
        "impacto": 3,
        "justificacion": "La omisión se presentó en el 25% de la muestra evaluada (5 de 20), lo que sugiere una frecuencia posible en la práctica clínica. La ausencia de información clave de enfermería puede derivar en afectaciones moderadas en la atención y seguridad del paciente hospitalizado."
      },
      "controles": [
        {
          "descripcion": "La Coordinación de Enfermería debe realizar rondas de auditoría concurrente semanal sobre las historias clínicas del servicio para verificar el diligenciamiento completo y oportuno de las valoraciones de enfermería.",
          "tipo": "PREVENTIVO",
          "criterio_id": "92b3dba7-f25f-4b16-b11c-6fb25eb7da05"
        },
        {
          "descripcion": "El personal de enfermería responsable del turno debe subsanar y completar los registros clínicos pendientes de los pacientes actualmente hospitalizados correspondientes a los casos identificados.",
          "tipo": "CORRECTIVO",
          "criterio_id": "0e29270c-fc1f-4ce5-a61f-5f763ad5bbfb"
        }
      ],
      "severidad": "media"
    }
  ]
}

{
  "hallazgos": [
    {
      "clasificacion": "FORTALEZA",
      "justificacion": "Se identifica una práctica positiva sistemática y destacada consistente en el seguimiento periódico a los indicadores y el uso efectivo de los resultados para la toma de decisiones y definición de acciones, generando un beneficio tangible y actual en la gestión y mejora continua del proceso.",
      "hallazgo_corregido": "El seguimiento mensual a los indicadores y la utilización de sus resultados para definir acciones, porque permite la toma de decisiones informada y favorece la mejora continua del proceso de gestión de calidad.",
      "criterio_requisito": "NTC-ISO 9001:2015, numeral 9.1.3 (Análisis y evaluación)",
      "evidencia": "El equipo realiza seguimiento mensual a los indicadores y utiliza los resultados para definir acciones.",
      "criterios_citados": [
        {
          "criterio_id": "a93c29f1-815d-4d4d-81b4-356caffa4c21",
          "numeral": "9.1.3",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": null,
      "controles": [],
      "severidad": "baja"
    }
  ]
}

{
  "hallazgos": [
    {
      "clasificacion": "OBSERVACION",
      "justificacion": "No existe un incumplimiento directo de un requisito específico en los criterios dados, pero la falta de legibilidad en las firmas representa una debilidad que afecta la trazabilidad de la información.",
      "hallazgo_corregido": "Se evidencia falta de legibilidad en algunas firmas de los registros, situación que podría impactar la trazabilidad y la identificación del personal responsable en el proceso.",
      "criterio_requisito": "[Requisito específico pendiente de identificación/validación]",
      "evidencia": "Registros completados con firmas poco legibles.",
      "criterios_citados": [],
      "riesgo": {
        "descripcion": "Posibilidad de pérdida de trazabilidad debido a firmas poco legibles, lo que podría dificultar la identificación de los responsables en los registros.",
        "dimension": "CALIDAD_SEGURIDAD_PACIENTE",
        "probabilidad": 2,
        "impacto": 2,
        "justificacion": "Se estima una probabilidad 2 (improbable) dado que los registros están completos pero aisladamente presentan esta debilidad, y un impacto 2 (menor) porque genera un reproceso leve para identificar al responsable."
      },
      "controles": [
        {
          "descripcion": "Implementar la validación de la legibilidad de la firma al momento de diligenciar el registro por parte del personal de Consulta Externa.",
          "tipo": "PREVENTIVO"
        }
      ],
      "severidad": "baja"
    }
  ]
}

{
  "hallazgos": [
    {
      "clasificacion": "OPORTUNIDAD_DE_MEJORA",
      "justificacion": "El proceso cumple con la actividad de registro de asistencia de manera correcta mediante formato físico, sin evidenciar incumplimiento de requisitos normativos ni debilidades significativas, existiendo una posibilidad de optimizar el proceso.",
      "hallazgo_corregido": "El método utilizado para el registro de asistencia es susceptible de mejorar, para lo cual se puede digitalizar el formato, lo que permitirá agilizar la consolidación de la información y facilitar su análisis.",
      "criterio_requisito": "[Requisito específico pendiente de identificación/validación]",
      "evidencia": "El registro de asistencia actualmente se realiza correctamente en formato físico.",
      "criterios_citados": [],
      "riesgo": {
        "descripcion": "Posibilidad de pérdida de información debido al uso de formato físico en el registro de asistencia, lo que podría dificultar la consolidación oportuna de los datos.",
        "dimension": "PRESTACION_SERVICIO",
        "probabilidad": 2,
        "impacto": 2,
        "justificacion": "Se estima una probabilidad baja dado que el proceso se realiza correctamente aunque en medio físico, y un impacto menor ya que los reprocesos en la consolidación no afectan directamente la atención a los pacientes."
      },
      "controles": [
        {
          "descripcion": "Revisar periódicamente el archivo físico de los registros de asistencia para verificar su integridad. Responsable: Gestión humana. Frecuencia: Mensual.",
          "tipo": "PREVENTIVO",
          "criterio_id": ""
        }
      ],
      "severidad": "baja"
    }
  ]
}

{
  "hallazgos": [
    {
      "clasificacion": "NO_CONFORMIDAD",
      "justificacion": "Se evidencia el incumplimiento de un requisito normativo obligatorio de la NTC-ISO 9001:2015, ya que en la revisión por la dirección no se incluyeron las decisiones y acciones frente a las oportunidades de mejora.",
      "hallazgo_corregido": "En la revisión por la dirección no se incluyeron las decisiones y acciones relacionadas con las oportunidades de mejora, incumpliendo lo establecido en la NTC-ISO 9001:2015, numeral 9.3.3.",
      "criterio_requisito": "NTC-ISO 9001:2015 numeral 9.3.3",
      "evidencia": "No se incluyeron las decisiones y acciones frente a las oportunidades de mejora en la revisión por la dirección.",
      "criterios_citados": [
        {
          "criterio_id": "9a8f5414-9eeb-4e24-a708-bf739832f494",
          "numeral": "9.3.3",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": {
        "descripcion": "Posibilidad de desalineación estratégica y estancamiento en la gestión debido a la omisión de decisiones sobre oportunidades de mejora en la revisión por la dirección, lo que podría afectar la eficacia del sistema de gestión de la calidad.",
        "dimension": "CALIDAD_SEGURIDAD_PACIENTE",
        "probabilidad": 2,
        "impacto": 2,
        "justificacion": "Se estima una probabilidad 2 (Improbable) por presentarse en el ciclo de revisión anual, y un impacto 2 (Menor) debido a que genera reprocesos o falta de direccionamiento sin comprometer de forma crítica la seguridad inmediata del paciente."
      },
      "controles": [
        {
          "descripcion": "Incluir obligatoriamente un acápite en el acta de revisión por la dirección dedicado a las decisiones y acciones sobre oportunidades de mejora, verificado por el área de Gestión Gerencial.",
          "tipo": "PREVENTIVO",
          "criterio_id": "9a8f5414-9eeb-4e24-a708-bf739832f494"
        },
        {
          "descripcion": "Revisar la trazabilidad de las actas de revisión por la dirección antes de su cierre definitivo.",
          "tipo": "CORRECTIVO",
          "criterio_id": "9a8f5414-9eeb-4e24-a708-bf739832f494"
        }
      ],
      "severidad": "media"
    }
  ]
}

{
  "hallazgos": [
    {
      "clasificacion": "OPORTUNIDAD_DE_MEJORA",
      "justificacion": "No se evidencia incumplimiento de un requisito normativo o institucional obligatorio que fije una capacidad mínima de parqueadero, ni se reporta una falla que impida la operación del servicio hospitalario; no obstante, existe una posibilidad de optimizar la infraestructura y logística de parqueo para mejorar la comodidad y el acceso de los usuarios.",
      "hallazgo_corregido": "La capacidad y gestión del parqueadero de visitantes es susceptible de mejorar, para lo cual se podrían implementar alternativas de señalización, control de cupos o convenios de estacionamiento, lo que permitirá optimizar la accesibilidad, el confort y la comodidad de los usuarios durante los días de mayor afluencia.",
      "criterio_requisito": "NTC-ISO 9001:2015, numeral 7.1.3",
      "evidencia": "Durante la auditoría se identificó que el parqueadero de visitantes cuenta con una capacidad limitada, llenándose en su totalidad los días viernes.",
      "criterios_citados": [
        {
          "criterio_id": "04cb2e5f-3c72-497d-a1bd-5bbb46d1b67f",
          "numeral": "7.1.3",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": {
        "descripcion": "Posibilidad de congestión y quejas de los usuarios debido a la capacidad limitada del parqueadero de visitantes los días viernes, lo que podría afectar levemente la percepción del servicio.",
        "dimension": "REPUTACIONAL",
        "probabilidad": 4,
        "impacto": 2,
        "justificacion": "Se estima una probabilidad probable (4) al ocurrir de manera recurrente cada semana (los viernes), y un impacto menor (2) dado que una eventual molestia en el estacionamiento afecta de forma leve la percepción del usuario pero puede ser gestionada sin comprometer la atención médica institucional ni generar repercusiones mayores en medios o redes."
      },
      "controles": [
        {
          "descripcion": "El área de Gestión de recursos físicos evaluará la viabilidad de implementar señalización de disponibilidad en tiempo real y convenios con parqueaderos aledaños para contingencias de alta demanda.",
          "tipo": "PREVENTIVO",
          "criterio_id": "04cb2e5f-3c72-497d-a1bd-5bbb46d1b67f"
        }
      ],
      "severidad": "baja"
    }
  ]
}

{
  "hallazgos": [
    {
      "clasificacion": "NO_CONFORMIDAD",
      "justificacion": "Se evidencia el incumplimiento de una condición de infraestructura y entorno seguro para la operación del servicio al contar con un equipo contra incendios (extintor) vencido en el área de Urgencias.",
      "hallazgo_corregido": "Durante la auditoría en el área de Urgencias se evidenció la presencia de un extintor vencido, incumpliendo con el aseguramiento del entorno adecuado para la operación de los procesos, establecido en la NTC-ISO 9001:2015, numeral 8.5.1.",
      "criterio_requisito": "NTC-ISO 9001:2015, numeral 8.5.1",
      "evidencia": "Extintor vencido en el área de urgencias.",
      "criterios_citados": [
        {
          "criterio_id": "ecf4dbe2-d038-4366-bd09-4b1d15e6ffe4",
          "numeral": "8.5.1",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": {
        "descripcion": "Posibilidad de inoperatividad ante conatos de incendio debido a la falta de vigencia en la recarga e inspección de extintores en el servicio de urgencias, lo que podría ocasionar afectaciones graves en la integridad física de pacientes y colaboradores.",
        "dimension": "CALIDAD_SEGURIDAD_PACIENTE",
        "probabilidad": 2,
        "impacto": 4,
        "justificacion": "La ocurrencia de un conato de incendio es poco frecuente (improbable), pero al estar el extintor vencido no se garantiza la contención oportuna de la emergencia, lo cual podría derivar en un deterioro serio de la salud o riesgo vital para usuarios y personal del área de Urgencias."
      },
      "controles": [
        {
          "descripcion": "El área de Mantenimiento / Seguridad y Salud en el Trabajo debe realizar el reemplazo o recarga inmediata del extintor vencido identificado en el área de Urgencias.",
          "tipo": "CORRECTIVO",
          "criterio_id": "ecf4dbe2-d038-4366-bd09-4b1d15e6ffe4"
        },
        {
          "descripcion": "El área de Seguridad y Salud en el Trabajo debe implementar una ronda mensual documentada de inspección de extintores en Urgencias para verificar fechas de vencimiento y estado operativo.",
          "tipo": "PREVENTIVO",
          "criterio_id": "ecf4dbe2-d038-4366-bd09-4b1d15e6ffe4"
        }
      ],
      "severidad": "media"
    },
    {
      "clasificacion": "FORTALEZA",
      "justificacion": "Se identifica una práctica positiva destacada en el personal respecto al conocimiento y aplicación del protocolo asistencial crítico de código azul, lo cual aporta a la oportunidad y seguridad en la atención de emergencias vitales.",
      "hallazgo_corregido": "El dominio del protocolo de código azul por parte del personal del área de Urgencias, porque favorece la respuesta oportuna y segura ante emergencias médicas de los pacientes.",
      "criterio_requisito": "NTC-ISO 9001:2015, numeral 7.2",
      "evidencia": "El personal de urgencias muestra dominio del protocolo de código azul.",
      "criterios_citados": [
        {
          "criterio_id": "3f390922-16a9-493b-aa29-7f9803bd6036",
          "numeral": "7.2",
          "documento": "NTC-ISO 9001:2015"
        }
      ],
      "riesgo": null,
      "controles": [],
      "severidad": "baja"
    }
  ]
}
